<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gohade</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hade v0.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span></span>
